[
  {
    "statement": "Pond creation and restoration are effective and cost-efficient methods for amphibian habitat restoration.",
    "citations": []
  },
  {
    "statement": "Creating new ponds has proven to be a highly successful method for restoring amphibian habitats.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Studies have shown that amphibians naturally colonized between 64% and 100% of created ponds.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Amphibians reproduced in 64% to 68% of newly created ponds.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Some newly created ponds have been able to naturally support up to 15 amphibian species.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Pond restoration was effective at increasing the number of amphibian species.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Restoring ponds has been shown to maintain or increase amphibian populations.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Breeding success for amphibians was achieved in 35% to 65% of restored ponds.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Engaging landowners and volunteers to manage land for amphibians is a particularly cost-effective approach.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Studies have shown that between 8 and 41,000 volunteers participated in habitat restoration programs.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Volunteer-based habitat restoration programs have restored up to 1,023 ponds.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Volunteer-based habitat restoration programs have restored over 11,500 square kilometers of habitat.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Payment schemes for farmers to cover conservation costs have proven effective in creating breeding habitat for amphibians.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Payment schemes for farmers have been effective in increasing amphibian populations.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Simple management actions such as deepening, de-silting, or re-profiling existing ponds resulted in the establishment of breeding populations for various amphibian species.",
    "citations": [
      "817"
    ]
  },
  {
    "statement": "Breeding populations of species including great crested newts and tree frogs were established through simple pond management actions.",
    "citations": [
      "817"
    ]
  }
]

[
  {
    "statement": "There is currently no direct evidence regarding the effectiveness of planting new hedges specifically for creating corridors for amphibians.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effects of planting hedges on amphibian populations.",
    "citations": [
      "791"
    ]
  },
  {
    "statement": "No evidence was found for the effects of maintaining or restoring hedges on amphibian populations.",
    "citations": [
      "790"
    ]
  },
  {
    "statement": "Restoring habitat connectivity between wetlands can benefit amphibians.",
    "citations": [
      "840"
    ]
  },
  {
    "statement": "One study in Italy found that raising a road on a viaduct to restore connectivity between two wetlands significantly decreased deaths of migrating amphibians.",
    "citations": [
      "840"
    ]
  },
  {
    "statement": "Newly planted hedges had a higher abundance, species richness, or diversity of beetles and spiders compared to crop fields.",
    "citations": [
      "538"
    ]
  },
  {
    "statement": "No specific data was collected on amphibians in studies on hedge effectiveness for other species like beetles and spiders.",
    "citations": [
      "538"
    ]
  },
  {
    "statement": "The evidence base currently lacks studies that directly test whether hedges are effective as amphibian corridors.",
    "citations": []
  }
]

[
  {
    "statement": "There is no documented research on the impact of reducing tillage on farmland for local amphibian populations.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "Multiple systematic searches found no evidence for the effects of reduced tillage on amphibian populations.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "No studies have been found that directly and quantitatively tested the effects of reduced tillage practices on amphibians.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "Reduced tillage has been shown to have various effects on other wildlife groups including earthworms, some invertebrates, weeds, and farmland birds.",
    "citations": []
  },
  {
    "statement": "Specific evidence for the effects of reduced tillage on amphibians is lacking in the current scientific literature.",
    "citations": []
  }
]

[
  {
    "statement": "No evidence was found for the effects of commercially breeding amphibians for the pet trade on wild amphibian populations.",
    "citations": []
  },
  {
    "statement": "A review found that reducing trade in two frog species through legislation allowed populations to recover from over-exploitation.",
    "citations": []
  },
  {
    "statement": "Reducing trade in two frog species through legislation allowed the frog populations to recover from over-exploitation.",
    "citations": []
  }
]

[
  {
    "statement": "Three before-and-after studies found that great crested newts successfully established breeding populations in 57-75% of created ponds.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Studies showed that up to 88% of created ponds were colonized by great crested newts.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Reproduction occurred in 38% of ponds for head-started great crested newt individuals.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Key factors affecting the success of ponds for great crested newts include vegetation cover, water levels, surrounding habitat, distance to source ponds, and the absence of fish.",
    "citations": [
      "869"
    ]
  },
  {
    "statement": "Seven amphibian species studies found that created wetlands had similar or higher numbers of species compared to natural wetlands when the created wetlands were designed appropriately.",
    "citations": [
      "880"
    ]
  },
  {
    "statement": "Specific cost information is not provided in the available studies about creating new ponds for great crested newts.",
    "citations": []
  },
  {
    "statement": "Pond creation appears to be an effective conservation method for great crested newts when suitable habitat requirements are met.",
    "citations": []
  }
]

[
  {
    "statement": "Based on available evidence, there is no direct research on the effectiveness of planting new hedges for increasing amphibian populations.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effects of planting hedges on amphibian populations.",
    "citations": [
      "791",
      "790"
    ]
  },
  {
    "statement": "No evidence was found for the effects of maintaining or restoring hedges on amphibian populations.",
    "citations": [
      "791",
      "790"
    ]
  },
  {
    "statement": "The lack of evidence means that no studies have been found that directly and quantitatively tested the action of planting hedges for amphibians during systematic journal and report searches.",
    "citations": []
  },
  {
    "statement": "One study that examined other biodiversity aspects of planting hedgerows found zero studies related to amphibians.",
    "citations": [
      "1415"
    ]
  },
  {
    "statement": "The effectiveness of planting new hedges for increasing amphibian populations remains unknown due to insufficient scientific evidence.",
    "citations": []
  }
]

[
  {
    "statement": "Action documents focused primarily on road-related impacts on amphibians.",
    "citations": []
  },
  {
    "statement": "Action documents did not provide specific evidence about traffic noise pollution effects on amphibian breeding success.",
    "citations": []
  },
  {
    "statement": "Roads significantly affect amphibians during breeding migrations.",
    "citations": []
  },
  {
    "statement": "Studies indicate that 64-70% of amphibian populations still declined over 6-10 years despite human assistance across roads.",
    "citations": []
  },
  {
    "statement": "Thousands of amphibians continue to be killed on roads even with mitigation measures in place.",
    "citations": []
  },
  {
    "statement": "Barrier fencing and culverts/tunnels have been used to reduce road deaths.",
    "citations": []
  },
  {
    "statement": "Barrier fencing and culverts/tunnels address road mortality rather than noise pollution impacts on breeding success.",
    "citations": []
  },
  {
    "statement": "Speed bumps and traffic calming structures have been installed to reduce vehicle speeds.",
    "citations": []
  },
  {
    "statement": "Reducing vehicle speeds could potentially reduce noise levels.",
    "citations": []
  },
  {
    "statement": "No direct evidence was found regarding how traffic noise specifically affects amphibian breeding success.",
    "citations": []
  }
]
